What does this C program print? It counts the MACs of a convolution on a $9 \times 9$ input with a $3 \times 3$ kernel and stride $U = 2$ (no padding; 32-bit `int`, 64-bit `long`).

```c
#include <stdio.h>
int main(void) {
  enum { N = 1, M = 2, C = 3, H = 9, R = 3, U = 2 };
  enum { P = (H - R) / U + 1 };  /* output height = width */
  long macs = 0;
  for (int n = 0; n < N; n++) for (int m = 0; m < M; m++)
    for (int c = 0; c < C; c++) for (int p = 0; p < P; p++)
      for (int q = 0; q < P; q++) for (int r = 0; r < R; r++)
        for (int s = 0; s < R; s++) macs++;
  printf("%ld\n", macs);
}
```

What does this C program print? (It spreads a 1-D output of $P = 10$ positions over 4 PEs with a kernel of $R = 3$ taps; 32-bit `int`.)

```c
#include <stdio.h>
enum { P = 10, R = 3, PES = 4 };
int main(void) {
  int macs = 0, idle = 0;
  for (int p2 = 0; p2 < (P + PES - 1) / PES; p2++)
    for (int p1 = 0; p1 < PES; p1++)
      for (int r = 0; r < R; r++) {
        if (p2 * PES + p1 < P) macs++;
        else idle++;
      }
  printf("%d %d\n", macs, idle);
}
```

What does this program print? (Python 3.) It counts the words of tiles loaded into a buffer for $C = AB$ with loop order $m, k, n$, reloading a tile only when it changes.

```python
M, N, K, T = 8, 12, 8, 4
reads_A = reads_B = 0
last_A = last_B = None
for m in range(0, M, T):
    for k in range(0, K, T):
        for n in range(0, N, T):
            if (m, k) != last_A: reads_A += T * T; last_A = (m, k)
            if (k, n) != last_B: reads_B += T * T; last_B = (k, n)
print(reads_A, reads_B)
```
